#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    const long long MOD = 1000000007;
    long long n, k;
    cin >> n >> k;
    long long p;
    if (k < 2) {
        p = n - (1 - k);
    } else {
        long long cycle_length = 1;
        long long value = k;
        while (value != 1) {
            value = (value * k) % n;
            cycle_length++;
        }
        p = (n - 1) / cycle_length;
    }
    long long result = 1;
    long long base = n % MOD;
    long long exponent = p;
    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exponent >>= 1;
    }
    cout << result << "\n";
    return 0;
}
